//! Actual Core + production HTTPS service + proof-bound loopback composition.
//! Provider identities and clock changes are disposable fixture inputs, not
//! real Twitch/Google or Noita evidence. Root explicitly serializes execution.
use super::*;
use std::{io::{BufRead,BufReader,Write},path::{Path,PathBuf},process::{Child,Command,Stdio}};
use crate::secrets::WindowsCredentialStore;
