#[path="next_host_death_composition_test.rs"]mod host_death_composition;
fn repo()->PathBuf{Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..").canonicalize().unwrap()}
struct Fixture{child:Child,events:Receiver<Value>,reader:Option<std::thread::JoinHandle<()>>,private:Value,closed:bool}
impl Fixture{
 fn start(root:&Path)->Self{
  Self::start_script(root,"apps/service/scripts/auth1-fixture-host.ts")
 }
 fn start_script(root:&Path,script:&str)->Self{
  assert!(matches!(script,"apps/service/scripts/auth1-fixture-host.ts"|"apps/desktop/tools/ux1-start-fixture.ts"|"apps/desktop/tools/ux1-host-death-fixture.ts"));
  use std::os::windows::process::CommandExt;
  let mut child=Command::new("C:/Program Files/nodejs/node.exe").creation_flags(0x08000000).current_dir(repo()).args(["--import","tsx",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(std::fs::File::create(root.join("service-stderr.txt")).unwrap()).spawn().unwrap();
  let output=child.stdout.take().unwrap();let(tx,events)=mpsc::channel();let reader=std::thread::spawn(move||{for line in BufReader::new(output).lines(){let Ok(line)=line else{break};if let Ok(v)=serde_json::from_str::<Value>(&line){let _=tx.send(v);}}});
  let until=Instant::now()+Duration::from_secs(60);let descriptor=loop{let v=events.recv_timeout(until.saturating_duration_since(Instant::now())).expect("AUTH1 fixture readiness deadline");if v["ready"]==true{break PathBuf::from(v["descriptor"].as_str().unwrap())}};
  let private=serde_json::from_slice(&std::fs::read(descriptor).unwrap()).unwrap();Self{child,events,reader:Some(reader),private,closed:false}
 }
 fn command(&mut self,mut input:Value)->Value{
  let id=uuid::Uuid::new_v4().to_string();input["requestId"]=id.clone().into();writeln!(self.child.stdin.as_mut().unwrap(),"{input}").unwrap();self.child.stdin.as_mut().unwrap().flush().unwrap();let until=Instant::now()+Duration::from_secs(20);
  loop{let v=self.events.recv_timeout(until.saturating_duration_since(Instant::now())).expect("AUTH1 fixture control deadline");if v["requestId"]!=id{continue}assert!(v["ok"]==true,"AUTH1 fixture operation refused");return serde_json::from_slice(&std::fs::read(v["responsePath"].as_str().unwrap()).unwrap()).unwrap()}
 }
 fn close(&mut self){if self.closed{return}self.child.stdin.take();let until=Instant::now()+Duration::from_secs(30);loop{if let Some(status)=self.child.try_wait().unwrap(){assert!(status.success(),"AUTH1 fixture cleanup failed");break}assert!(Instant::now()<until,"AUTH1 fixture cooperative cleanup deadline");std::thread::sleep(Duration::from_millis(25));}self.reader.take().unwrap().join().unwrap();let mut cleaned=false;while let Ok(v)=self.events.try_recv(){if v["verifiedAbsentSchema"].as_str()==self.private["namespace"].as_str(){cleaned=true;}}assert!(cleaned,"AUTH1 fixture schema absence not verified");self.closed=true;}
}
impl Drop for Fixture{fn drop(&mut self){if !self.closed{self.close();}}}
#[derive(Clone)]struct Protected{origin:String,profiles:Arc<Mutex<Vec<ServiceProfile>>>}
impl Protected{fn check(&self,p:&ServiceProfile){assert_eq!(p.origin(),self.origin);let mut entries=self.profiles.lock().unwrap();if !entries.contains(p){entries.push(p.clone());}}}
impl CredentialStore for Protected{
 fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.check(p);WindowsCredentialStore.load(p)}
 fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{self.check(p);WindowsCredentialStore.save(p,b)}
 fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.check(p);WindowsCredentialStore.delete(p)}
}
struct Stores(Vec<Protected>);
impl Drop for Stores{fn drop(&mut self){for store in &self.0{for p in store.profiles.lock().unwrap().iter(){WindowsCredentialStore.delete(p).unwrap();assert!(WindowsCredentialStore.load(p).unwrap().is_none());}}}}
fn client(f:&Fixture,root:&Path,stores:&mut Stores)->Core<Protected>{
 let origin=f.private["origin"].as_str().unwrap();let store=Protected{origin:origin.into(),profiles:Default::default()};stores.0.push(store.clone());std::fs::create_dir_all(root).unwrap();let mut c=Core::new(store,uuid::Uuid::new_v4(),Arc::new(Mutex::new(None)),root.to_path_buf());c.open_browser=false;c.world_files=Arc::new(nt2_desktop_g0::world_store::Files::ephemeral_fixture(root.join("worlds")).unwrap());
 let ca=reqwest::Certificate::from_pem(&std::fs::read(f.private["caPath"].as_str().unwrap()).unwrap()).unwrap();c.http=reqwest::Client::builder().use_native_tls().tls_certs_only(vec![ca]).no_proxy().redirect(reqwest::redirect::Policy::none()).timeout(Duration::from_secs(5)).build().unwrap();c
}
fn attribute(tag:&str,key:&str)->Option<String>{tag.split_once(&format!("{key}=\""))?.1.split_once('"').map(|(v,_)|v.replace("&quot;","\"").replace("&#39;","'").replace("&lt;","<").replace("&gt;",">").replace("&amp;","&"))}
fn form(html:&str)->(String,Vec<(String,String)>){let tag=html.split("<form ").nth(1).expect("AUTH1 browser form missing");let action=attribute(tag.split('>').next().unwrap(),"action").unwrap();let fields=tag.split("<input ").filter_map(|input|{let input=input.split('>').next()?;if attribute(input,"type").as_deref()!=Some("hidden"){return None}Some((attribute(input,"name")?,attribute(input,"value")?))}).collect();(action,fields)}
struct Browser{http:reqwest::Client,origin:String,cookies:std::collections::BTreeMap<String,String>}
impl Browser{
 fn new(c:&Core<Protected>)->Self{Self{http:c.http.clone(),origin:c.base.clone(),cookies:Default::default()}}
 async fn request(&mut self,url:&str,fields:Option<Vec<(String,String)>>)->(u16,Option<String>,String){
  let parsed=reqwest::Url::parse(url).unwrap();let service=parsed.origin().ascii_serialization()==self.origin;
  assert!(service||parsed.scheme()=="http"&&parsed.host_str()==Some("127.0.0.1")&&parsed.port().is_some(),"AUTH1 fixture browser origin refused");
  let mut request=if let Some(fields)=fields{let mut encoded=reqwest::Url::parse("http://127.0.0.1/").unwrap();encoded.query_pairs_mut().extend_pairs(fields);self.http.post(url).header("origin",&self.origin).header("content-type","application/x-www-form-urlencoded").body(encoded.query().unwrap_or("").to_owned())}else{self.http.get(url)};
  if service&&!self.cookies.is_empty(){request=request.header("cookie",self.cookies.iter().filter(|(k,_)|!k.starts_with("nt2-flow-")||parsed.path().starts_with("/auth")).map(|(k,v)|format!("{k}={v}")).collect::<Vec<_>>().join("; "));}
  let response=request.send().await.expect("AUTH1 browser request failed");let status=response.status().as_u16();if service{for value in response.headers().get_all("set-cookie"){let head=value.to_str().unwrap().split(';').next().unwrap();if let Some((k,v))=head.split_once('='){self.cookies.insert(k.into(),v.into());}}}let location=response.headers().get("location").map(|v|v.to_str().unwrap().to_owned());let text=response.text().await.unwrap();assert!(text.len()<65536);(status,location,text)
 }
 async fn page(&mut self,url:&str)->(u16,String){let mut url=url.to_owned();for _ in 0..8{let(status,location,text)=self.request(&url,None).await;if let Some(location)=location{url=reqwest::Url::parse(&url).unwrap().join(&location).unwrap().to_string();continue}return(status,text)}panic!("AUTH1 browser redirect bound")}
 async fn handoff(&mut self,c:&mut Core<Protected>,html:&str){let(action,fields)=form(html);let expected=c.auth.as_ref().unwrap().return_url(c.generation.load(Ordering::Acquire)).unwrap();assert!(action==expected,"AUTH1 browser callback target differs");let(status,_,_)=self.request(&action,Some(fields.clone())).await;assert_eq!(status,200,"AUTH1 one-use handoff refused");let until=Instant::now()+Duration::from_secs(5);while c.desktop.is_none(){c.auth_tick().await.unwrap();assert!(Instant::now()<until,"AUTH1 exchange deadline");tokio::time::sleep(Duration::from_millis(10)).await;}let mut encoded=reqwest::Url::parse("http://127.0.0.1/").unwrap();encoded.query_pairs_mut().extend_pairs(fields);let replay=self.http.post(&action).header("origin",&self.origin).header("content-type","application/x-www-form-urlencoded").body(encoded.query().unwrap().to_owned()).send().await;assert!(replay.is_err()||replay.unwrap().status().as_u16()>=400);}
 async fn provider(&mut self,c:&mut Core<Protected>){let(status,location,_)=self.request(c.pending_launch.as_ref().unwrap(),None).await;assert_eq!(status,302);let(status,callback,_)=self.request(&location.unwrap(),None).await;assert_eq!(status,302);let callback=callback.unwrap();let(status,html)=self.page(&callback).await;assert_eq!(status,200,"AUTH1 provider browser flow refused");self.handoff(c,&html).await;assert!(self.page(&callback).await.0>=400,"AUTH1 provider callback replay accepted");}
 async fn local(&mut self,c:&mut Core<Protected>,username:&str,password:&str,replacement:Option<&str>){let(status,html)=self.page(c.pending_launch.as_ref().unwrap()).await;assert_eq!(status,200);let(action,mut fields)=form(&html);assert_eq!(action,"/auth/local");fields.extend([("username".into(),username.into()),("password".into(),password.into())]);let(status,_,mut html)=self.request(&format!("{}{}",self.origin,action),Some(fields)).await;assert_eq!(status,200,"AUTH1 local login refused");if let Some(replacement)=replacement{let(action,mut fields)=form(&html);assert_eq!(action,"/auth/password");assert!(c.desktop.is_none(),"AUTH1 temporary password issued general desktop session");fields.push(("password".into(),replacement.into()));let(status,_,next)=self.request(&format!("{}{}",self.origin,action),Some(fields)).await;assert_eq!(status,200,"AUTH1 forced replacement refused");html=next;}self.handoff(c,&html).await;}
}
async fn projection(c:&mut Core<Protected>)->Value{c.auth1.next_account=None;c.auth1.account_job=None;let until=Instant::now()+Duration::from_secs(6);loop{c.poll_auth1();let v=c.auth1_view();if !v["account"].is_null(){return v["account"].clone()}assert!(Instant::now()<until,"AUTH1 current projection deadline: active={} discovered={} options={} account={}",c.auth1.active,v["discovered"],v["options_error"],v["account_error"]);tokio::time::sleep(Duration::from_millis(20)).await;}}
#[test]#[ignore="Root-serialized disposable DB composition only"]fn auth1_actual_desktop_service_browser_and_roles(){
 assert_eq!(std::env::var("NT2_AUTH1_COMPOSITION").as_deref(),Ok("1"));let root=repo().join("spikes/noita-entry/.build").join(format!("auth1-composition-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();
 tauri::async_runtime::block_on(async{
  let mut f=Fixture::start(&root);let mut stores=Stores(Vec::new());let origin=f.private["origin"].as_str().unwrap().to_owned();let mut a=client(&f,&root.join("google"),&mut stores);let mut b=client(&f,&root.join("twitch"),&mut stores);
  a.login(&origin,true,"google",None,None).await.unwrap();b.login(&origin,true,"twitch",None,None).await.unwrap();assert_ne!(a.auth.as_ref().unwrap().begin.callback_port,b.auth.as_ref().unwrap().begin.callback_port);
  let mut browser_a=Browser::new(&a);let mut browser_b=Browser::new(&b);browser_a.provider(&mut a).await;browser_b.provider(&mut b).await;assert_ne!(a.desktop.as_ref().unwrap().account,b.desktop.as_ref().unwrap().account);assert_eq!(projection(&mut a).await["role"],"user");assert_eq!(projection(&mut b).await["role"],"user");
  let profile=a.profile.as_ref().unwrap().clone();let remembered=WindowsCredentialStore.load(&profile).unwrap().unwrap();let record:Value=serde_json::from_slice(remembered.bytes()).unwrap();assert!(record.as_object().unwrap().keys().all(|k|["revision","device","refresh","request_id","started"].contains(&k.as_str())));assert!(record["refresh"].is_string());
  let mut cold=client(&f,&root.join("restored"),&mut stores);cold.device=a.device;cold.login(&origin,true,"google",None,None).await.unwrap();assert!(cold.auth.is_none()&&cold.desktop.is_some(),"AUTH1 protected restore unexpectedly opened sign-in");assert_eq!(cold.desktop.as_ref().unwrap().account,a.desktop.as_ref().unwrap().account);a.desktop=None;a=cold;
  let lobby=f.command(json!({"op":"create-lobby"}));let room=lobby["room"]["roomId"].as_str().unwrap();a.join(room,None).await.unwrap();b.join(room,None).await.unwrap();assert_eq!(a.room.as_ref().unwrap().room_id.as_deref(),Some(room));
  let account=a.desktop.as_ref().unwrap().account.clone();f.command(json!({"op":"role","accountId":account,"role":"power-user"}));a.auth1.account=None;assert_eq!(projection(&mut a).await["entitlements"]["customLobbyName"],true);f.command(json!({"op":"role","accountId":account,"role":"user"}));a.auth1.account=None;assert_eq!(projection(&mut a).await["entitlements"]["customLobbyName"],false);assert_eq!(a.room.as_ref().unwrap().room_id.as_deref(),Some(room));b.room_page(false).await.unwrap();
  let created=zeroize::Zeroizing::new(f.command(json!({"op":"local-create","username":"client_fixture","displayName":"Client fixture"})).to_string());let local:Value=serde_json::from_str(&created).unwrap();let mut local_client=client(&f,&root.join("local"),&mut stores);local_client.login(&origin,true,"local",None,None).await.unwrap();let mut local_browser=Browser::new(&local_client);local_browser.local(&mut local_client,"client_fixture",local["temporaryPassword"].as_str().unwrap(),Some("Synthetic replacement password 42!")).await;assert_eq!(projection(&mut local_client).await["provider"],"local");local_client.join(room,None).await.unwrap();
  let mut returning=client(&f,&root.join("local-returning"),&mut stores);returning.login(&origin,true,"local",None,None).await.unwrap();Browser::new(&returning).local(&mut returning,"client_fixture","Synthetic replacement password 42!",None).await;assert_eq!(returning.desktop.as_ref().unwrap().account,local_client.desktop.as_ref().unwrap().account);
  let(status,html)=local_browser.page(&format!("{origin}/auth/password")).await;assert_eq!(status,200);let(action,mut fields)=form(&html);assert_eq!(action,"/auth/local");fields.extend([("username".into(),"client_fixture".into()),("password".into(),"Synthetic replacement password 42!".into())]);let(status,location,_)=local_browser.request(&format!("{origin}{action}"),Some(fields)).await;assert_eq!(status,302);assert_eq!(location.as_deref(),Some("/auth/password"));let(status,html)=local_browser.page(&format!("{origin}/auth/password")).await;assert_eq!(status,200);let(action,mut fields)=form(&html);assert_eq!(action,"/auth/password");fields.extend([("currentPassword".into(),"Synthetic replacement password 42!".into()),("password".into(),"Synthetic changed password 43!".into())]);assert_eq!(local_browser.request(&format!("{origin}{action}"),Some(fields)).await.0,302);assert!(local_client.rotate().await.is_err());assert!(returning.rotate().await.is_err());
  local_client.desktop=None;let mut changed=client(&f,&root.join("local-password-changed"),&mut stores);changed.login(&origin,true,"local",None,None).await.unwrap();Browser::new(&changed).local(&mut changed,"client_fixture","Synthetic changed password 43!",None).await;local_client=changed;
  f.command(json!({"op":"reset-local","accountId":local["account"]["accountId"]}));assert!(local_client.rotate().await.is_err(),"AUTH1 reset did not revoke desktop refresh");assert!(returning.rotate().await.is_err(),"AUTH1 reset did not revoke other local family");b.room_page(false).await.unwrap();assert!(b.desktop.is_some());
  let mut cancelled=client(&f,&root.join("cancel"),&mut stores);cancelled.login(&origin,false,"google",None,None).await.unwrap();let launch=cancelled.pending_launch.clone().unwrap();cancelled.cancel_sign_in().await.unwrap();let mut cancelled_browser=Browser::new(&cancelled);assert!(cancelled_browser.page(&launch).await.0>=400);assert!(cancelled.desktop.is_none());
  for fault in ["audience","issuer","nonce","expired","outage"]{f.command(json!({"op":"provider-fault","provider":"google","fault":fault}));let mut denied=client(&f,&root.join(format!("denied-{fault}")),&mut stores);denied.login(&origin,false,"google",None,None).await.unwrap();let mut browser=Browser::new(&denied);let(status,html)=browser.page(denied.pending_launch.as_ref().unwrap()).await;assert!(status>=400||html.contains("Sign-in was cancelled or could not be verified"),"AUTH1 invalid provider identity accepted: {fault}");assert!(!html.contains("id=\"return\""));assert!(denied.desktop.is_none());denied.cancel_sign_in().await.unwrap();f.command(json!({"op":"provider-clear"}));}
  let mut wrong_state=client(&f,&root.join("wrong-state"),&mut stores);wrong_state.login(&origin,false,"google",None,None).await.unwrap();let mut browser=Browser::new(&wrong_state);let(_,authorization,_)=browser.request(wrong_state.pending_launch.as_ref().unwrap(),None).await;let(_,callback,_)=browser.request(&authorization.unwrap(),None).await;let mut callback=reqwest::Url::parse(&callback.unwrap()).unwrap();let query:Vec<_>=callback.query_pairs().map(|(k,v)|{let state=k=="state";(k.into_owned(),if state{"x".repeat(43)}else{v.into_owned()})}).collect();callback.set_query(None);callback.query_pairs_mut().extend_pairs(query);assert!(browser.page(callback.as_str()).await.0>=400);assert!(wrong_state.desktop.is_none());wrong_state.cancel_sign_in().await.unwrap();
  let mut expired=client(&f,&root.join("expired-attempt"),&mut stores);expired.login(&origin,false,"google",None,None).await.unwrap();f.command(json!({"op":"advance","ms":300001}));let mut browser=Browser::new(&expired);assert!(browser.page(expired.pending_launch.as_ref().unwrap()).await.0>=400);assert!(expired.desktop.is_none());expired.cancel_sign_in().await.unwrap();
  local_client.desktop=None;local_client.logout().await.unwrap();a.rotate().await.unwrap();a.logout().await.unwrap();b.rotate().await.unwrap();b.room_page(false).await.unwrap();b.logout().await.unwrap();drop(stores);f.close();
  std::fs::write(root.join("result.json"),serde_json::to_vec_pretty(&json!({"passed":true,"providerFacts":"synthetic Google/Twitch HTTP/JWKS; actual production validation","actualConsumers":["Core discovery","proof-bound loopback","NT2 exchange","Windows protected remembered store","lobby join/current state","role projection","local forced replacement","reset/session revocation","unaffected peer","cancel","logout"],"realProviderSmoke":false,"noitaLaunched":false,"schemaCleanupVerified":true})).unwrap()).unwrap();eprintln!("AUTH1 composition passed: {}",root.display());
 });
}
